#!/usr/bin/env node
// Vendor a built, private @ichava library into a host repository.
//
//   node .dev/tools/sync-vendored-library.mjs --package <name> --source <checkout> --target <dir>
//        [--type-dependency <name>]... [--generated-by <script path>] [--root <host root>]
//
// SHARED FILE. This script is byte-identical in every host that vendors an @ichava library
// (ichava/icon-browser for @ichava/react-icon-browser, ichava/ichava.com for
// @ichava/react-landingpage). Change it in one host, copy it to the others, and check with
// `cmp`. A host's own defaults live in a thin wrapper next to it, never in this file.
//
// Why vendor instead of installing: the libraries are private, so an npm git dependency would
// need a GitHub token on every CI run and every deploy, and it would install `src/` without the
// `dist/lib` build. Instead the built output is copied in with a manifest, vendored.json, naming
// the exact commit and a SHA-256 for every file, which the host's test checks.
//
// Refuses: a checkout that is not the named package, one with no `dist/lib/index.js`, one with
// uncommitted changes to its source or build config, and a `dist/lib` older than HEAD.
//
// Never copies `*.map`: a map's sourcesContent is the readable library source, Untitled UI PRO
// included, and nothing at runtime reads it.
//
// Refuses, before touching the target, any `baseline/` path and any SVG from
// icon-sets-metronic or icon-sets-bundled in what it would copy. react-icon-browser's
// `public/baseline/` holds Metronic and bundled SVGs for its rendering tests, and Vite copies
// it into `dist/`; both packs are private to Simtabi LLC (Sim, 2026-10-26), so that sample
// may stay where it is but must never be copied into anything public.

import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { cpSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { join, relative, resolve, sep } from 'node:path';
import { pathToFileURL } from 'node:url';

export class SyncError extends Error {}

/** Path segments and SVG paths that must never be vendored (see the header). */
const BASELINE_SEGMENT = /(^|\/)baseline(\/|$)/i;
const PRIVATE_PACK_SVG = /(icon-sets-metronic|icon-sets-bundled|metronic)[^]*\.svg$/i;

/** The manifest's file name. Lowercase slug, like every file name (it was VENDORED.json). */
export const MANIFEST = 'vendored.json';

/**
 * The paths, relative and `/`-separated, that may not be vendored: anything under a
 * `baseline/` directory, and any SVG whose path names icon-sets-metronic, icon-sets-bundled
 * or Metronic. Empty when the set is clean.
 */
export function privateContent(paths) {
  return paths.filter((p) => BASELINE_SEGMENT.test(p) || PRIVATE_PACK_SVG.test(p)).sort();
}

/**
 * The vendored copy's own package.json: the library's `dist/lib` exports with the prefix
 * dropped, no source entry points, stylesheets marked as side effects, the named
 * type-only dependencies (the declarations import their types; the JS has them bundled),
 * and the peers left as peers.
 */
export function vendoredManifest(pkg, { typeDependencies = [], generatedBy }) {
  const LIB = './dist/lib/';
  const rewrite = (v) => {
    if (typeof v === 'string') return v.startsWith(LIB) ? `./${v.slice(LIB.length)}` : null;
    const out = {};
    for (const [k, inner] of Object.entries(v ?? {})) {
      const r = rewrite(inner);
      if (r !== null) out[k] = r;
    }
    return Object.keys(out).length ? out : null;
  };
  const exports = {};
  for (const [key, value] of Object.entries(pkg.exports ?? {})) {
    if (key === './package.json') {
      exports[key] = './package.json';
      continue;
    }
    const r = rewrite(value);
    if (r !== null) exports[key] = r;
  }
  if (!exports['.']) throw new SyncError(`${pkg.name} exports nothing from ${LIB}`);
  const sideEffects = Object.values(exports).filter((v) => typeof v === 'string' && v.endsWith('.css'));
  const dependencies = {};
  for (const name of typeDependencies) {
    const range = pkg.dependencies?.[name];
    if (!range) throw new SyncError(`${pkg.name} does not depend on ${name}`);
    dependencies[name] = range;
  }
  return {
    name: pkg.name,
    version: pkg.version,
    private: true,
    license: pkg.license,
    type: 'module',
    description: `Vendored build of ${pkg.name}. Generated by ${generatedBy}; do not edit.`,
    types: rewrite(pkg.types) ?? './types/index.d.ts',
    exports,
    sideEffects,
    ...(typeDependencies.length ? { dependencies } : {}),
    peerDependencies: pkg.peerDependencies,
  };
}

/** `https://github.com/o/r` from a package.json `repository` (string or object). */
export function repositoryUrl(pkg) {
  const raw = typeof pkg.repository === 'string' ? pkg.repository : pkg.repository?.url;
  if (!raw) throw new SyncError(`${pkg.name} has no repository`);
  return raw.replace(/^git\+/, '').replace(/\.git$/, '');
}

export function syncVendoredLibrary({ packageName, source, target, typeDependencies = [], generatedBy, root, license = (text) => text }) {
  const lib = join(source, 'dist', 'lib');
  if (!existsSync(join(source, 'package.json'))) throw new SyncError(`no package.json in ${source}`);
  const pkg = JSON.parse(readFileSync(join(source, 'package.json'), 'utf8'));
  if (pkg.name !== packageName) throw new SyncError(`${source} is ${pkg.name}, not ${packageName}`);
  if (!existsSync(join(lib, 'index.js'))) throw new SyncError(`no ${relative(root, lib)}/index.js; run \`npm run build:lib\` there first`);

  const walk = (dir) =>
    readdirSync(dir, { withFileTypes: true }).flatMap((d) => (d.isDirectory() ? [join(dir, d.name) + sep, ...walk(join(dir, d.name))] : [join(dir, d.name)]));
  // Checked before the target is cleared, so a refused sync leaves the vendored copy as it was.
  const refused = privateContent(walk(lib).map((f) => relative(lib, f).split(sep).join('/') + (f.endsWith(sep) ? '/' : '')));
  if (refused.length) {
    throw new SyncError(
      `refusing to vendor ${refused.length} private path(s) from ${relative(root, lib)}: baseline/ and Metronic or bundled SVGs never leave react-icon-browser (${refused.slice(0, 5).join(', ')}${refused.length > 5 ? ', …' : ''})`,
    );
  }

  const git = (...args) => execFileSync('git', ['-C', source, '-c', 'core.fsmonitor=false', ...args], { encoding: 'utf8' }).trim();
  const commit = git('rev-parse', 'HEAD');
  const dirty = git('status', '--porcelain', '--untracked-files=no', '--', 'src', 'package.json', 'vite.lib.config.ts');
  if (dirty) throw new SyncError(`${source} has uncommitted changes under src/ or the build config; vendor a commit, not a working tree`);
  const committedAt = Number(git('log', '-1', '--format=%ct')) * 1000;
  if (statSync(join(lib, 'index.js')).mtimeMs < committedAt) throw new SyncError('dist/lib is older than HEAD; rebuild it with `npm run build:lib`');

  const manifest = vendoredManifest(pkg, { typeDependencies, generatedBy });
  // The host may reword the library's LICENSE for the copy it ships (`license`, text in, text out).
  // Applied before the target is cleared, so a refusal leaves the vendored copy as it was, and
  // written before the manifest is hashed, so vendored.json always matches what is on disk.
  const licenseText = license(readFileSync(join(source, 'LICENSE'), 'utf8'));

  rmSync(target, { recursive: true, force: true });
  mkdirSync(target, { recursive: true });
  cpSync(lib, target, { recursive: true, filter: (src) => !src.endsWith('.map') });
  writeFileSync(join(target, 'LICENSE'), licenseText);
  // Maps are not shipped, so drop each JS file's comment pointing at its own (bundlers warn on a
  // missing map). Every file, not only index.js: a library with more than one entry splits its
  // code into chunks, and each chunk names its map.
  for (const file of walk(target).filter((f) => f.endsWith('.js'))) {
    writeFileSync(file, readFileSync(file, 'utf8').replace(/\n\/\/# sourceMappingURL=[^\n]+\.js\.map\s*$/, '\n'));
  }
  writeFileSync(join(target, 'package.json'), JSON.stringify(manifest, null, 2) + '\n');

  const files = Object.fromEntries(
    walk(target)
      .filter((f) => !f.endsWith(sep))
      .map((f) => relative(target, f).split(sep).join('/'))
      .filter((f) => f !== MANIFEST)
      .sort()
      .map((f) => [f, createHash('sha256').update(readFileSync(join(target, f))).digest('hex')]),
  );
  if (files['index.js.map'] || Object.keys(files).some((f) => f.endsWith('.map'))) throw new SyncError('a source map reached the target');
  if (privateContent(Object.keys(files)).length) throw new SyncError('a baseline/ path or a Metronic or bundled SVG reached the target');

  writeFileSync(
    join(target, MANIFEST),
    JSON.stringify(
      { package: pkg.name, version: pkg.version, repository: repositoryUrl(pkg), commit, builtWith: 'npm run build:lib', files },
      null,
      2,
    ) + '\n',
  );
  return { pkg, commit, files };
}

/** Parse `--flag value` pairs; `--type-dependency` may repeat. */
export function parseArgs(argv) {
  const out = { typeDependencies: [] };
  for (let i = 0; i < argv.length; i += 2) {
    const [flag, value] = [argv[i], argv[i + 1]];
    if (value === undefined || value.startsWith('--')) throw new SyncError(`${flag} needs a value`);
    if (flag === '--package') out.packageName = value;
    else if (flag === '--source') out.source = value;
    else if (flag === '--target') out.target = value;
    else if (flag === '--root') out.root = value;
    else if (flag === '--generated-by') out.generatedBy = value;
    else if (flag === '--type-dependency') out.typeDependencies.push(value);
    else throw new SyncError(`unknown option ${flag}`);
  }
  for (const k of ['packageName', 'source', 'target']) if (!out[k]) throw new SyncError(`--${k === 'packageName' ? 'package' : k} is required`);
  return out;
}

/** Run with logging and exit codes; `name` prefixes every line (the wrapper's name). */
export function run(options, name = 'sync-vendored-library') {
  const root = resolve(options.root ?? process.cwd());
  const source = resolve(root, options.source);
  const target = resolve(root, options.target);
  try {
    const { pkg, commit, files } = syncVendoredLibrary({
      ...options,
      root,
      source,
      target,
      generatedBy: options.generatedBy ?? '.dev/tools/sync-vendored-library.mjs',
    });
    console.log(`${name}: ${pkg.name}@${pkg.version} (${commit.slice(0, 7)}), ${Object.keys(files).length} files -> ${relative(root, target)}`);
  } catch (e) {
    if (!(e instanceof SyncError)) throw e;
    console.error(`${name}: ${e.message}`);
    process.exit(1);
  }
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  try {
    run(parseArgs(process.argv.slice(2)));
  } catch (e) {
    if (!(e instanceof SyncError)) throw e;
    console.error(`sync-vendored-library: ${e.message}`);
    process.exit(1);
  }
}
